import{_ as t,c as r,o as e,a6 as l}from"./chunks/framework.CZHnDj0c.js";const y=JSON.parse('{"title":"相机核心图像参数速查手册","description":"","frontmatter":{},"headers":[],"relativePath":"src/camera/ISP.md","filePath":"src/camera/ISP.md"}'),o={name:"src/camera/ISP.md"},s=l('<h1 id="相机核心图像参数速查手册" tabindex="-1">相机核心图像参数速查手册 <a class="header-anchor" href="#相机核心图像参数速查手册" aria-label="Permalink to &quot;相机核心图像参数速查手册&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本文档旨在提炼关键图像参数的核心作用，助您快速理解并应用。所有处理均由相机ISP（图像信号处理器）完成。</p><hr><h2 id="参数核心作用一览" tabindex="-1">参数核心作用一览 <a class="header-anchor" href="#参数核心作用一览" aria-label="Permalink to &quot;参数核心作用一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">参数</th><th style="text-align:left;">核心作用</th><th style="text-align:left;">好比</th><th style="text-align:left;">调整建议</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>白平衡 (WB)</strong></td><td style="text-align:left;"><strong>校正颜色偏差</strong>，使白色在任何光线下都显白。</td><td style="text-align:left;">让照片脱掉“有色眼镜”（如偏黄、偏蓝）。</td><td style="text-align:left;"><strong>优先自动(AWB)</strong>。偏色时，手动选择对应光源模式（如白炽灯图标）或对白纸校准。</td></tr><tr><td style="text-align:left;"><strong>饱和度 (Saturation)</strong></td><td style="text-align:left;"><strong>控制颜色的鲜艳程度</strong>。</td><td style="text-align:left;">调色盘的颜料纯度。越高越艳丽，越低越朴素。</td><td style="text-align:left;">适度增加(+1)让风光、食物更诱人。过度调整会色彩失真、缺乏层次。</td></tr><tr><td style="text-align:left;"><strong>锐度 (Sharpness)</strong></td><td style="text-align:left;"><strong>增强边缘轮廓，提升清晰感</strong>。</td><td style="text-align:left;">给图像“画边线”，让细节更突出。</td><td style="text-align:left;">适度增加(+1)让细节更清晰。过度调整会产生不自然白边和噪点。</td></tr><tr><td style="text-align:left;"><strong>色调 (Tone)</strong></td><td style="text-align:left;"><strong>控制整体颜色倾向</strong>（偏暖或偏冷）。</td><td style="text-align:left;">给整个画面统一叠加一层色纱（如偏黄或偏蓝）。</td><td style="text-align:left;">微调可营造氛围（如人像稍偏暖显肤色红润，风景稍偏冷显通透）。</td></tr><tr><td style="text-align:left;"><strong>伽马 (Gamma)</strong></td><td style="text-align:left;"><strong>优化明暗对比与亮度层次</strong>。</td><td style="text-align:left;">压缩亮部、提亮暗部，让照片告别“灰蒙蒙”。</td><td style="text-align:left;">通常默认即可。<strong>LOG模式</strong>即是大幅降低伽马以记录更多亮暗细节，供后期调整。</td></tr></tbody></table><hr><h2 id="核心技术原理" tabindex="-1">核心技术原理 <a class="header-anchor" href="#核心技术原理" aria-label="Permalink to &quot;核心技术原理&quot;">​</a></h2><h3 id="bayer插值-demosaic" tabindex="-1">Bayer插值 (Demosaic) <a class="header-anchor" href="#bayer插值-demosaic" aria-label="Permalink to &quot;Bayer插值 (Demosaic)&quot;">​</a></h3><ul><li><strong>作用</strong>：将传感器捕获的<strong>黑白马赛克（RAW）数据，“猜”出全彩图像</strong>的核心算法。</li><li><strong>须知</strong>：这是RAW转JPG的第一步，所有后续调整都基于此。算法优劣直接影响细节和伪色（彩色条纹）。</li></ul><hr><h2 id="实践应用举例" tabindex="-1">实践应用举例 <a class="header-anchor" href="#实践应用举例" aria-label="Permalink to &quot;实践应用举例&quot;">​</a></h2><ol><li><p><strong>拍摄人像</strong></p><ul><li><strong>白平衡</strong>：稍向<strong>暖调（+）</strong> 调整，使肤色显得红润、健康。</li><li><strong>饱和度</strong>：<strong>适度（+1）</strong>，让唇色和衣物颜色更自然好看。</li><li><strong>锐度</strong>：<strong>适度（+1）</strong>，让发丝和眼部细节更清晰。</li><li><strong>目标</strong>：打造自然、温馨、细节丰富的肖像。</li></ul></li><li><p><strong>拍摄风景</strong></p><ul><li><strong>白平衡</strong>：选择“日光”模式，或保持自动，还原真实色彩。</li><li><strong>饱和度</strong>：可<strong>适当提高（+1~2）</strong>，让天空更蓝、植物更绿。</li><li><strong>锐度</strong>：<strong>直接提高（+2）</strong>，让建筑物、树叶纹理更清晰。</li><li><strong>目标</strong>：获得色彩鲜明、细节锐利的壮观画面。</li></ul></li><li><p><strong>拍摄食物</strong></p><ul><li><strong>白平衡</strong>：务必准确，避免食物看起来发黄（像变质）或发蓝（没食欲）。</li><li><strong>饱和度</strong>：<strong>适度提高（+1）</strong>，让食物看起来更新鲜、诱人。</li><li><strong>色调</strong>：可稍向<strong>暖调（+）</strong> 微调，增加温暖和食欲感。</li><li><strong>目标</strong>：拍出令人垂涎欲滴的美食照片。</li></ul></li><li><p><strong>后期创作</strong></p><ul><li><strong>色调</strong>：大幅向<strong>冷调（-）</strong> 调整，可营造清冷、未来感或孤独氛围。</li><li><strong>饱和度</strong>：<strong>大幅降低</strong>，可打造简约、冷淡或怀旧的风格。</li><li><strong>伽马</strong>：拍摄<strong>LOG/Flat模式</strong>（低伽马），为后期调色保留最大亮暗信息。</li></ul></li></ol><hr><h2 id="核心关系总结" tabindex="-1">核心关系总结 <a class="header-anchor" href="#核心关系总结" aria-label="Permalink to &quot;核心关系总结&quot;">​</a></h2><ol><li><p><strong>工作流程</strong>： <code>Bayer插值</code> → <code>白平衡</code> → （<code>色调/饱和度</code>调整） → <code>锐化</code> → <code>伽马编码</code> → 输出JPG。</p></li><li><p><strong>调整优先级</strong>： <strong>先调白平衡</strong>确定色彩基准，再调饱和度/色调定义风格，最后用锐度增强细节。伽马通常保持默认。</p></li><li><p><strong>黄金法则</strong>： <strong>宁缺毋滥</strong>。所有参数的微调（±1）通常优于大幅调整，以保持画面的自然和真实感。</p></li></ol>',16),n=[s];function a(g,i,d,h,c,f){return e(),r("div",null,n)}const u=t(o,[["render",a]]);export{y as __pageData,u as default};
